@push('scripts')
<script>
let fanChart=null;
async function openChart(name,id){
 document.getElementById('chartTitle').textContent='Grafik suhu · '+name;
 const modal=document.getElementById('chartModal');modal.classList.remove('hidden');modal.classList.add('flex');
 try{
  const response=await fetch(`{{ url('/api/fans') }}/${id}/history`,{headers:{'Accept':'application/json'}});
  let rows=response.ok?await response.json():[];
  const labels=rows.map(r=>r.recorded_at);const values=rows.map(r=>Number(r.temperature));
  document.getElementById('chartEmpty').classList.toggle('hidden',values.length>0);
  if(fanChart)fanChart.destroy();
  fanChart=new Chart(document.getElementById('temperatureChart'),{type:'line',data:{labels,datasets:[{label:'Suhu (°C)',data:values,borderColor:'#2563eb',backgroundColor:'rgba(37,99,235,.12)',fill:true,tension:.35,pointRadius:3}]},options:{responsive:true,plugins:{legend:{display:true}},scales:{y:{title:{display:true,text:'Suhu °C'}},x:{title:{display:true,text:'Waktu'}}}}});
 }catch(e){document.getElementById('chartEmpty').classList.remove('hidden');if(fanChart)fanChart.destroy();fanChart=new Chart(document.getElementById('temperatureChart'),{type:'line',data:{labels:[],datasets:[{label:'Suhu (°C)',data:[]}]}});}
}
function closeChart(){document.getElementById('chartModal').classList.add('hidden');document.getElementById('chartModal').classList.remove('flex');}
document.getElementById('chartModal').addEventListener('click',e=>{if(e.target.id==='chartModal')closeChart()});
</script>
